def seed_testcases(db):
    if db.query(SecurityTestCase).count() > 0:
        return
    for row in CASES:
        code, cat, title, module, role, sev, toggle, desc, obj, proc, ind, exp, fix, refs, api_type, auth = row[:16]
        tech = row[16] if len(row) > 16 else "fastapi"
        if cat == "GraphQL Security":
            tech = "graphql"
        t = SecurityTestCase(code=code, category=cat, title=title, description=desc, module=module, preconditions=f"Seeded environment. {'Signed in as ' + role.replace('_', ' ') + '.' if role != 'anonymous' else 'No sign-in required.'}",
                             required_role=role, objective=obj, procedure=proc, expected_secure=exp, indicators=ind, severity=sev, evidence=EVIDENCE, remediation=fix, references=refs, auth_required=auth,
                             api_type=api_type, technology=tech, execution="manual", vuln_toggle=toggle)
        db.add(t)
        db.flush()
        db.add(SecurityTestCaseVersion(test_case_id=t.id, version=1, snapshot={k: getattr(t, k) for k in ("code", "category", "title", "severity", "vuln_toggle")}))
